#!/usr/bin/env bash
# D5: generated bytes and container identities, independent of the plugin install tree.
set -euo pipefail
export LC_ALL=C
sha256() {
  if command -v sha256sum >/dev/null; then sha256sum "$1"; else shasum -a 256 "$1"; fi
}
if [[ $# != 1 || ! -d $1 ]]; then
  echo 'usage: gen-manifest.sh PROJECT_DIR' >&2
  exit 2
fi
cd "$1"
root=$PWD
compose=(docker compose)
files=(docker-compose.yml)
if [[ -f .nself/compose-files.txt ]]; then
  files=()
  while IFS= read -r path || [[ -n $path ]]; do files+=("$path"); done < .nself/compose-files.txt
fi
for path in "${files[@]}"; do
  [[ -n $path && -f $path ]] && compose+=(-f "$path")
done
if [[ -f .nself/compose-env-files.txt ]]; then
  while IFS= read -r path; do
    [[ -n $path && -f $path ]] && compose+=(--env-file "$path")
  done < .nself/compose-env-files.txt
fi
if [[ -f .nself/compose.env && ! -s .nself/compose-env-files.txt ]]; then
  echo 'compose env manifest missing or empty: run nself build' >&2
  exit 1
fi
{
  {
    printf '%s\n' docker-compose.yml
    for path in "${files[@]}"; do printf '%s\n' "${path#"$root/"}"; done
    [[ ! -f .env.computed ]] || printf '%s\n' .env.computed
    for tree in nginx ssl .nself/generated; do
      [[ ! -d $tree ]] || find -L "$tree" -type f -print
    done
  } | sort -u | while IFS= read -r path; do
    [[ -n $path && -f $path ]] || continue
    relative=${path#"$root/"}
    printf '%s  %s\n' "$(sha256 "$path" | cut -d ' ' -f 1)" "$relative"
  done
  project=$("${compose[@]}" config --format json | jq -er .name)
  "${compose[@]}" ps -a --format json | jq -rs '
    (if length == 1 and (.[0]|type) == "array" then .[0] else . end)[] |
    "service \(.Service) \(.State)"'
  docker ps -a --filter "label=com.docker.compose.project=$project" --format '{{json .}}' |
    jq -rs '.[] | "container \(.Names) \(.State)"'
  ids=$(docker ps -aq --filter "label=com.docker.compose.project=$project")
  if [[ -n $ids ]]; then
    # IDs are Docker-generated hex tokens, so intentional splitting is safe.
    # shellcheck disable=SC2086
    docker inspect $ids | jq -r '.[] | "image \(.Config.Labels["com.docker.compose.service"]) \(.Image)"'
  fi
} | sort
